// Helios Studio in Picacho's four languages (stage 7, 2026-09-29 — operator:
// "Pushed, keep going."). Blender translates its interface by the English
// text itself (gettext: the English string is the key), and so does the
// Studio: each row is [English, Spanish (es-ES, "tú"), Portuguese (pt-BR,
// "você"), Italian]. A row with {0}, {1}… is a pattern for text built with
// values; the values are passed through (numbers in the locale's form).
// Standard terms use the words Blender's own es/pt/it interfaces use; where
// Blender keeps the English word (Layout, Render, Track To, Array…), so does
// this. Keys stay keys. Object names are the person's data and are never
// translated (the outliner and name fields show them as they are).

export type StudioRow = readonly [en: string, es: string, pt: string, it: string];

